#include "emnext/io/optimizer_io.hpp"
#include <boost/json.hpp>
#include <fstream>
#include <stdexcept>
namespace emnext::io { namespace json=boost::json; namespace {
json::object metrics_json(const optimization::CandidateMetrics& m){return {{"score",m.score},{"vswr",m.vswr},{"forward_gain_dbi",m.forward_gain_dbi},{"front_to_back_db",m.front_to_back_db},{"boom_length_m",m.boom_length_m},{"power_balance_relative_error",m.power_balance_relative_error},{"max_linear_residual_relative",m.max_linear_residual_relative},{"worst_vswr_frequency_hz",m.worst_vswr_frequency_hz},{"min_gain_frequency_hz",m.min_gain_frequency_hz},{"min_front_to_back_frequency_hz",m.min_front_to_back_frequency_hz},{"feasible",m.feasible},{"violated_constraints",m.violated_constraints},{"total_constraint_violation",m.total_constraint_violation}};}
json::object candidate_json(const optimization::CandidateResult& c){json::array values;for(const auto& v:c.values) values.emplace_back(json::object{{"id",v.id},{"value",v.value}});json::array violations;for(const auto& v:c.constraint_violations) violations.emplace_back(json::object{{"id",v.id},{"kind",v.kind},{"amount",v.amount},{"normalized_amount",v.normalized_amount}});return {{"model_hash",c.model_hash},{"values",std::move(values)},{"metrics",metrics_json(c.metrics)},{"constraint_violations",std::move(violations)}};}
}
std::string optimizer_to_json(const optimization::OptimizerResult& r){json::object weights{{"match",r.weights.match},{"gain",r.weights.gain},{"front_to_back",r.weights.front_to_back},{"size",r.weights.size}};json::object root{{"schema_version",r.schema_version},{"algorithm",r.algorithm},{"objective",r.objective},{"linear_solver_backend",r.linear_solver_backend},{"execution_workers",r.execution_workers},{"scheduler_mode",r.scheduler_mode},{"seed",r.seed},{"population",r.population},{"generations",r.generations},{"local_iterations",r.local_iterations},{"evaluations",r.evaluations},{"evaluation_cache_hits",r.evaluation_cache_hits},{"weights",std::move(weights)},{"gain_guardrail_db",r.gain_guardrail_db},{"max_vswr",r.max_vswr},{"band_start_hz",r.band_start_hz},{"band_stop_hz",r.band_stop_hz},{"band_points",r.band_points},{"quantization_step_m",r.quantization_step_m},{"manufacturing_tolerance_m",r.manufacturing_tolerance_m},{"robust_objective_samples",r.robust_objective_samples},{"monte_carlo_samples",r.monte_carlo_samples},{"initial",candidate_json(r.initial)},{"best",candidate_json(r.best)}};root["initial_nominal"]=r.initial_nominal?json::value(candidate_json(*r.initial_nominal)):json::value(nullptr);root["best_nominal"]=r.best_nominal?json::value(candidate_json(*r.best_nominal)):json::value(nullptr);if(r.tolerance_audit){root["tolerance_audit"]=json::object{{"tolerance_m",r.tolerance_audit->tolerance_m},{"stress_cases",r.tolerance_audit->stress_cases},{"passes_guardrails",r.tolerance_audit->passes_guardrails},{"worst_case",metrics_json(r.tolerance_audit->worst_case)}};}else root["tolerance_audit"]=nullptr;if(r.monte_carlo_audit){root["monte_carlo_audit"]=json::object{{"tolerance_m",r.monte_carlo_audit->tolerance_m},{"samples",r.monte_carlo_audit->samples},{"passing_samples",r.monte_carlo_audit->passing_samples},{"pass_fraction",r.monte_carlo_audit->pass_fraction},{"p95_vswr",r.monte_carlo_audit->p95_vswr},{"p05_gain_dbi",r.monte_carlo_audit->p05_gain_dbi},{"p05_front_to_back_db",r.monte_carlo_audit->p05_front_to_back_db},{"worst_case",metrics_json(r.monte_carlo_audit->worst_case)}};}else root["monte_carlo_audit"]=nullptr;root["robust_best"]=r.robust_best?json::value(candidate_json(*r.robust_best)):json::value(nullptr);if(r.robust_tolerance_audit){root["robust_tolerance_audit"]=json::object{{"tolerance_m",r.robust_tolerance_audit->tolerance_m},{"stress_cases",r.robust_tolerance_audit->stress_cases},{"passes_guardrails",r.robust_tolerance_audit->passes_guardrails},{"worst_case",metrics_json(r.robust_tolerance_audit->worst_case)}};}else root["robust_tolerance_audit"]=nullptr;json::array pareto;for(const auto& c:r.pareto_front) pareto.emplace_back(candidate_json(c));root["pareto_front"]=std::move(pareto);json::array featured;for(const auto& n:r.featured_candidates) featured.emplace_back(json::object{{"label",n.label},{"candidate",candidate_json(n.candidate)}});root["featured_candidates"]=std::move(featured);json::array history;for(const auto& c:r.generation_best) history.emplace_back(candidate_json(c));root["generation_best"]=std::move(history);json::array local_history;for(const auto& c:r.local_refinement_best) local_history.emplace_back(candidate_json(c));root["local_refinement_best"]=std::move(local_history);json::array warnings;for(const auto& w:r.warnings) warnings.emplace_back(w);root["warnings"]=std::move(warnings);return json::serialize(root);}
void write_optimizer_json(const optimization::OptimizerResult& r,const std::filesystem::path& path){std::ofstream out(path);if(!out)throw std::runtime_error("Cannot create optimizer result file: "+path.string());out<<optimizer_to_json(r)<<'\n';}
} // namespace emnext::io
